package com.aaliyun.leadnews.search.web;
import com.aaliyun.leadnews.common.api.ResponseResult;import com.aaliyun.leadnews.common.context.UserContext;import com.aaliyun.leadnews.common.exception.BusinessException;import com.aaliyun.leadnews.search.domain.SearchHistory;import com.aaliyun.leadnews.search.service.*;import jakarta.validation.constraints.*;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;import java.util.*;
@Validated @RestController @RequestMapping("/api/search")public class SearchController{private final ArticleSearchService search;private final SearchHistoryService history;public SearchController(ArticleSearchService s,SearchHistoryService h){search=s;history=h;}
 @GetMapping("/articles")public ResponseResult<ArticleSearchService.SearchPage> articles(@RequestParam @NotBlank @Size(max=100)String keyword,@RequestParam(required=false)Long channelId,@RequestParam(defaultValue="1")@Min(1)int page,@RequestParam(defaultValue="10")@Min(1)@Max(50)int size,@RequestParam(defaultValue="RELEVANCE")@Pattern(regexp="RELEVANCE|TIME")String sort){return ResponseResult.success(search.search(keyword.trim(),channelId,page,size,sort));}
 @GetMapping("/suggestions")public ResponseResult<List<String>>suggestions(@RequestParam @NotBlank @Size(max=50)String prefix,@RequestParam(defaultValue="10")@Min(1)@Max(10)int size){return ResponseResult.success(search.suggest(prefix.trim(),size));}
 @GetMapping("/history")public ResponseResult<List<SearchHistory>>history(){return ResponseResult.success(history.list());}@DeleteMapping("/history")public ResponseResult<Void>clear(){history.clear();return ResponseResult.success();}@DeleteMapping("/history/{id}")public ResponseResult<Void>delete(@PathVariable Long id){history.delete(id);return ResponseResult.success();}}
